#!/usr/bin/env python3
"""Generate the version-free TypeScript semantic model from canonical BFBS metadata."""

from __future__ import annotations

import sys
from pathlib import Path

from searchkernel_bfbs import ReflectedSchema


def render(bfbs: Path) -> str:
    schema = ReflectedSchema(bfbs)
    lines = [
        "// Generated by tools/generate-typescript-semantic-model.py from BFBS; do not edit.",
        "// This version-free model deliberately contains no FlatBuffers classes.",
        "export class SemanticTable {",
        "  readonly _semanticTable = true;",
        "  protected constructor(",
        "    readonly _schemaName: string,",
        "    readonly _semanticFields: readonly string[],",
        "    args: readonly unknown[],",
        "    defaults: readonly unknown[],",
        "  ) {",
        "    this._semanticFields.forEach((field, index) => { (this as any)[field] = index < args.length ? args[index] : defaults[index]; });",
        "  }",
        "}",
        "export function isSemanticTable(value: unknown): value is SemanticTable { return value instanceof SemanticTable; }",
    ]

    enum_fields: list[tuple[str, list[tuple[str, str]]]] = []
    for obj in schema.wire_objects():
        name = schema.short_name(obj)
        fields = schema.fields(obj)
        field_names = [schema.field_name(field) for field in fields]
        parameter_names = [
            f"{field_name}_" if field_name in {"arguments", "eval"} else field_name
            for field_name in field_names
        ]
        defaults = [schema.ts_default(field) for field in fields]
        lines.append(f"export class {name}T extends SemanticTable {{")
        for field, field_name in zip(fields, field_names):
            lines.append(f"  declare {field_name}: {schema.ts_type(field)};")
        if fields:
            params = ", ".join(
                f"{parameter_name}: {schema.ts_type(field)} = {default}"
                for field, parameter_name, default in zip(fields, parameter_names, defaults)
            )
            field_list = ", ".join(repr(field_name) for field_name in field_names)
            arg_list = ", ".join(parameter_names)
            default_list = ", ".join(defaults)
            lines.append(
                f"  constructor({params}) {{ super({name!r}, [{field_list}], [{arg_list}], [{default_list}]); }}"
            )
        else:
            lines.append(f"  constructor() {{ super({name!r}, [], [], []); }}")
        lines.append("}")

        specs = [
            (schema.field_name(field), spec)
            for field in fields
            if (spec := schema.enum_spec(field)) is not None
        ]
        if specs:
            enum_fields.append((name, specs))

    for enum in schema.wire_enums():
        name = schema.short_name(enum)
        lines.append(f"export enum {name} {{")
        for member, value in schema.enum_values(enum):
            lines.append(f"  {member} = {value},")
        lines.append("}")

    lines.append(
        "export const SEMANTIC_ENUM_FIELDS: Readonly<Record<string, Readonly<Record<string, string>>>> = {"
    )
    for table_name, specs in enum_fields:
        entries = ", ".join(f"{field}: {enum_name!r}" for field, enum_name in specs)
        lines.append(f"  {table_name}: {{ {entries} }},")
    lines.append("};")
    return "\n".join(lines) + "\n"


def main() -> int:
    if len(sys.argv) != 3:
        raise SystemExit(
            "usage: generate-typescript-semantic-model.py SEARCHKERNEL_RESPONSE_BFBS OUTPUT"
        )
    bfbs = Path(sys.argv[1])
    output = Path(sys.argv[2])
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(render(bfbs), encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
